<?php
declare(strict_types=1);namespace App\Application\Reconciliation;
use App\Application\{Audit\AuditWriter,Events\OutboxWriter};use App\Domain\Reconciliation\MatchEngine;use App\Models\{PaymentIntentRecord,ReconciliationImport,ReconciliationItem,User};use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
final class ReconciliationService{public function __construct(private MatchEngine$engine,private AuditWriter$audit,private OutboxWriter$outbox,private ?OutcomeClassifier$classifier=null,private ?ReconciliationExceptionQueue$queue=null){$this->classifier??=app(OutcomeClassifier::class);$this->queue??=app(ReconciliationExceptionQueue::class);}public function import(?string$tenant,array$d,User$actor):ReconciliationImport{return DB::transaction(function()use($tenant,$d,$actor){if(ReconciliationImport::where('file_hash',$d['file_hash'])->exists())throw ValidationException::withMessages(['file_hash'=>__('wave4.statement_duplicate')]);$r=ReconciliationImport::create([...$d,'tenant_id'=>$tenant,'status'=>'PROCESSING','total_rows'=>count($d['items']),'uploaded_by'=>$actor->id]);$matched=0;$exceptions=0;foreach($d['items']as$row){$payment=PaymentIntentRecord::where('provider_reference',$row['external_reference'])->when($tenant,fn($q)=>$q->where('tenant_id',$tenant))->first();$o=$this->classifier->classify($row['external_reference'],(int)$row['gross_minor'],$d['currency'],$payment);$item=ReconciliationItem::create([...$row,'reconciliation_import_id'=>$r->id,'currency'=>$d['currency'],'status'=>$o['status'],'outcome'=>$o['outcome'],'expected_minor'=>$o['expected_minor'],'variance_minor'=>$o['variance_minor'],'matched_type'=>$payment?'PAYMENT_INTENT':null,'matched_id'=>$payment?->id,'exception_code'=>$o['exception_code'],'raw_data'=>$row]);if($o['status']==='MATCHED'){$matched++;$matched+=$this->completeSplit($item,$actor);}else{$exceptions++;$this->queue->raise($item,$tenant,$actor);}}$exceptions=$r->items()->where('status','EXCEPTION')->count();$matched=$r->items()->where('status','MATCHED')->count();unset($r->items);$r->update(['status'=>$exceptions?'COMPLETED_WITH_EXCEPTIONS':'COMPLETED','matched_rows'=>$matched,'exception_rows'=>$exceptions,'completed_at'=>now()]);$this->audit->record('reconciliation.completed','reconciliation_import',$r->id,['matched'=>$matched,'exceptions'=>$exceptions]);return$r->refresh();});}public function resolve(ReconciliationItem$i,array$d,User$actor):ReconciliationItem{if($i->status!=='EXCEPTION')throw ValidationException::withMessages(['status'=>__('wave4.exception_closed')]);if($d['resolution']==='MATCHED')throw ValidationException::withMessages(['resolution'=>'A manual match needs maker-checker: use POST reconciliation/items/{item}/manual-matches.']);$i->update(['status'=>$d['resolution'],'matched_type'=>$d['matched_type']??null,'matched_id'=>$d['matched_id']??null,'resolution_notes'=>$d['notes'],'resolved_by'=>$actor->id,'resolved_at'=>now()]);$this->audit->record('reconciliation.exception.resolved','reconciliation_item',$i->id,['resolution'=>$d['resolution']]);$this->queue->close($i,$d['resolution'],$actor);$this->recount($i->import);return$i->refresh();}public function approve(ReconciliationImport$r,User$actor):ReconciliationImport{if(!in_array($r->status,['COMPLETED','COMPLETED_WITH_EXCEPTIONS'],true)||$r->items()->where('status','EXCEPTION')->exists())throw ValidationException::withMessages(['status'=>__('wave4.reconciliation_not_approvable')]);if($r->uploaded_by===$actor->id)throw ValidationException::withMessages(['actor'=>__('wave4.maker_checker')]);$r->update(['status'=>'APPROVED','approved_by'=>$actor->id,'approved_at'=>now()]);$r->items()->where('status','MATCHED')->where('matched_type','PAYMENT_INTENT')->get()->each(function($x){PaymentIntentRecord::whereKey($x->matched_id)->update(['reconciled_at'=>now()]);/* REQ-OBL-001: settle the obligation the reconciled payment pays (idempotent). */try{if($p=PaymentIntentRecord::find($x->matched_id))app(\App\Application\Finance\Obligations\PolicyPremiumObligations::class)->settlePayment($p);}catch(\Throwable$e){report($e);}});$this->outbox->record('reconciliation.approved','reconciliation_import',$r->id,['reconciliation_import_id'=>$r->id]);return$r->refresh();}
/** A line that completes a split settlement promotes the earlier PARTIAL lines of the same payment to MATCHED; returns how many lines in the current import were promoted. */
private function completeSplit(ReconciliationItem$item,User$actor):int{$n=0;ReconciliationItem::where('matched_type','PAYMENT_INTENT')->where('matched_id',$item->matched_id)->where('outcome','PARTIAL')->where('status','EXCEPTION')->get()->each(function(ReconciliationItem$p)use($item,$actor,&$n){$p->update(['status'=>'MATCHED','exception_code'=>null,'resolution_notes'=>'Split settlement completed by line '.$item->external_reference,'resolved_by'=>$actor->id,'resolved_at'=>now()]);$this->queue->close($p,'MATCHED',$actor);if($p->reconciliation_import_id===$item->reconciliation_import_id)$n++;else$this->recount($p->import);});return$n;}
public function recount(ReconciliationImport$r):void{$ex=$r->items()->where('status','EXCEPTION')->count();$r->update(['matched_rows'=>$r->items()->where('status','MATCHED')->count(),'exception_rows'=>$ex]+(in_array($r->status,['COMPLETED','COMPLETED_WITH_EXCEPTIONS'],true)?['status'=>$ex?'COMPLETED_WITH_EXCEPTIONS':'COMPLETED']:[]));}}
